const path = require('node:path');
const fs = require('node:fs/promises');
const readline = require('node:readline');
const { spawn } = require('node:child_process');
const { chromium } = require(path.join(process.env.HOME, '.npm/_npx/69cf6d85e87fa9bf/node_modules/playwright'));

(async () => {
  const environment = { ...process.env };
  delete environment.DATABASE_URL;
  delete environment.RAILS_MASTER_KEY;
  const bridge = spawn('bundle', ['exec', 'ruby', 'tmp/terminology-v1/preview_bridge.rb'], { env: environment });
  bridge.stderr.on('data', () => {});
  const lines = readline.createInterface({ input: bridge.stdout });
  const reader = lines[Symbol.asyncIterator]();
  if (!JSON.parse((await reader.next()).value).ready) throw new Error('Preview boot failed');
  const browser = await chromium.launch({ headless: true });
  try {
    const page = await browser.newPage({ viewport: { width: 1280, height: 900 } });
    const submit = async locator => {
      await Promise.all([page.waitForNavigation({ waitUntil: 'domcontentloaded' }), locator.click()]);
    };
    let queue = Promise.resolve();
    await page.route('http://onni.rails.fi/**', route => {
      const task = queue.then(async () => {
        const request = route.request();
        bridge.stdin.write(JSON.stringify({ method: request.method(), url: request.url(), body: request.postData() || '', cookie: request.headers().cookie || '' }) + '\n');
        let response = JSON.parse((await reader.next()).value);
        if ([302, 303].includes(response.status)) {
          bridge.stdin.write(JSON.stringify({ method: 'GET', url: response.headers.location, cookie: request.headers().cookie || '' }) + '\n');
          response = JSON.parse((await reader.next()).value);
        }
        const headers = Object.fromEntries(Object.entries(response.headers).map(([name, value]) => [name, Array.isArray(value) ? value.join('\n') : String(value)]));
        await route.fulfill({ status: response.status, headers, body: response.body });
      });
      queue = task.catch(() => {});
      return task;
    });
    const output = path.join(process.cwd(), 'docs/reviews/assets');
    await fs.mkdir(output, { recursive: true });
    const row = name => page.locator('tr').filter({ has: page.getByRole('link', { name, exact: true }) });
    const check = (condition, message) => { if (!condition) throw new Error(message); };
    await page.goto('http://onni.rails.fi/admin/features');
    check(await row('demo').getByText('Ready', { exact: true }).count() > 0, 'Ready status missing');
    check(await row('audience').getByText('Parked', { exact: true }).count() > 0, 'Parked status missing');
    check(await row('search_v2').getByText('Pending', { exact: true }).count() > 0, 'Pending status missing');
    await page.screenshot({ path: path.join(output, '20261113091112_ready-park-visible-index.png'), fullPage: true });
    await submit(row('demo').getByRole('button', { name: 'Park', exact: true }));
    await page.goto('http://onni.rails.fi/admin/features');
    check(await row('demo').getByRole('button', { name: 'Ready', exact: true }).count() === 1, 'Park did not persist');
    await submit(row('demo').getByRole('button', { name: 'Ready', exact: true }));
    await page.goto('http://onni.rails.fi/admin/features/demo');
    check((await page.locator('[data-onni-shown-share]').textContent()).trim() === '80.0%', 'Shown share mismatch');
    await page.getByLabel('History', { exact: true }).selectOption('7d');
    await submit(page.getByRole('button', { name: 'Show', exact: true }));
    check(await page.locator('details tbody tr').count() === 7, 'History did not change');
    await page.locator('summary').click();
    await page.screenshot({ path: path.join(output, '20261113091112_ready-park-visible-history.png'), fullPage: true });
    await page.setViewportSize({ width: 390, height: 844 });
    await page.goto('http://onni.rails.fi/admin/features/search_v2');
    await page.getByLabel('Level (0-100)', { exact: true }).fill('40');
    await submit(page.getByRole('button', { name: 'Save', exact: true }));
    check(await page.getByLabel('Level (0-100)', { exact: true }).inputValue() === '40', 'Level did not persist');
    await page.screenshot({ path: path.join(output, '20261113091112_ready-park-visible-level-390.png'), fullPage: true });
    await page.goto('http://onni.rails.fi/admin/features/audience');
    await page.locator('select[name="group_name"]').selectOption('beta_testers');
    await page.locator('select[name="group_action"]').selectOption('visible');
    await submit(page.getByRole('button', { name: 'Save', exact: true }));
    check(await page.locator('[data-status="ready"]').count() > 0, 'Visible slice did not ready audience');
    await page.locator('select[name="group_name"]').selectOption('beta_testers');
    await page.locator('select[name="group_action"]').selectOption('drop');
    await submit(page.getByRole('button', { name: 'Save', exact: true }));
    check(await page.locator('[data-status="ready"]').count() > 0, 'Drop changed power');
    await page.goto('http://onni.rails.fi/admin/features/selected');
    check((await page.locator('[data-onni-shown-share]').textContent()).trim() === 'No data', 'Empty history missing');
    await page.screenshot({ path: path.join(output, '20261113091112_ready-park-visible-empty-390.png'), fullPage: true });
    const report = { powerCommands: 'passed', history: 'passed', levelSave: 'passed', groupActions: 'passed', emptyState: 'passed', viewports: [1280, 390], hostStyles: 'not installed in dummy app; rendered unstyled', redirects: 'Rack responses followed inside bridge; native redirect status covered by request specs' };
    await fs.writeFile('benchmarks/output/terminology_v1_visual.json', JSON.stringify(report, null, 2) + '\n');
    console.log(JSON.stringify(report));
  } finally {
    await browser.close();
    bridge.stdin.end();
    bridge.kill();
  }
})().catch(error => { console.error(error.message); process.exitCode = 1; });
